              |> drop(str_len(buf) - size)
              |> join("")
          }
        },
        Clear => buf = "",
        Enter => {
          if buf == code {
            state = "open"
            fails = 0
          } else {
            fails = fails + 1
            if fails >= 3 {
              state = "blocked"
            }
          }
          buf = ""
        },
      }
    }
  }
  return state
}

