    if (!s) {
      s = { pts: 0, gf: 0, ga: 0 };
      stats.set(t, s);
      order.push(t);
    }
    return s;
  };
  for (const m of matches) {
    const h = get(m.home);
    const a = get(m.away);
    h.gf += m.home_goals;
    h.ga += m.away_goals;
    a.gf += m.away_goals;
    a.ga += m.home_goals;
