    const a = get(m.away);
    h.gf += m.home_goals;
    h.ga += m.away_goals;
    a.gf += m.away_goals;
    a.ga += m.home_goals;
    if (m.home_goals > m.away_goals) {
      h.pts += 3;
      a.pts += 0;
    } else if (m.home_goals < m.away_goals) {
      h.pts += 0;
      a.pts += 3;
    } else {
