fn spiral_order(m: List[List[Int]]) -> List[Int] {
  var out = []
  let width = m
    |> first()
    |> unwrap_or([])
    |> len()
  if len(m) == 0 || width == 0 {
    return out
  }
  var top = 0
  var bottom = len(m) - 1
  var left = 0
  var right = width - 1
  while top <= bottom && left <= right {
