fn median(xs: List[Int]) -> Float {
  let s = sort_by(xs, |x| x)
  let n = len(s)
  let a = s
    |> drop((n - 1) / 2)
    |> first()
    |> unwrap_or(0)
  let b = s
    |> drop(n / 2)
    |> first()
    |> unwrap_or(0)
  return to_float(a + b) / 2.0
}

