  let cs = split(s, "")
  let n = len(cs)
  var i = 0
  var out = []
  while i < n {
    let c = at(cs, i)
    let two = c + at(cs, i + 1)
    if c == " " {
      i = i + 1
    } else if is_digit(c) {
      var v = 0
      while is_digit(at(cs, i)) {
        v = v * 10 + (cs |> at(i) |> parse_int() |> unwrap_or(0))
        i = i + 1
      }
      out = append(out, Num(v))
    } else if is_start(c) {
      var name = ""
      while is_start(at(cs, i)) || is_digit(at(cs, i)) {
        name = name + at(cs, i)
        i = i + 1
      }
