fn at(xs: List[Int], i: Int) -> Int {
  return xs
    |> drop(i)
    |> first()
    |> unwrap_or(0)
}

fn ch(xs: List[String], i: Int) -> String {
  if i < 0 {
    return ""
  }
  return xs
    |> drop(i)
    |> first()
    |> unwrap_or("")
