  if !is_digit(at(cs, j)) {
    return Err(bad(j))
  }
  var v = 0
  while is_digit(at(cs, j)) {
    v = v * 10 + (cs |> at(j) |> parse_int() |> unwrap_or(0))
    j = j + 1
  }
  return Ok((sign * v, j))
