  var n = 0
  for dr in [-1, 0, 1] {
    for dc in [-1, 0, 1] {
      if (dr != 0 || dc != 0) && cell(g, r + dr, c + dc) == "#" {
        n = n + 1
      }
    }
  }
  return n
}

