    kind: Literal["Leave"]
    plate: str
    minute: int

Park = Arrive | Leave


def parking_fees(events: list[Park]) -> list[tuple[str, int]]:
    """Total the fees of completed stays per plate, sorted by plate."""
    parked: dict[str, int] = {}
    totals: dict[str, int] = {}
    for event in events:
        plate = event["plate"]
        if event["kind"] == "Arrive":
            parked.setdefault(plate, event["minute"])
        elif plate in parked:
            arrival = parked.pop(plate)
            duration = event["minute"] - arrival
            totals[plate] = totals.get(plate, 0) + _stay_fee(duration)
    return sorted(totals.items())


