VOWELS = frozenset("aeiou")


def _is_vowel(word: str, i: int) -> bool:
    ch = word[i]
    if ch == "y":
        return i > 0
    if ch == "u" and i > 0 and word[i - 1] != "q":
        return False
    return ch in VOWELS


