    first_vowel = next((i for i in range(len(word)) if _is_vowel(word, i)), None)
    if first_vowel is None:
        return word + "ay"
    if first_vowel == 0:
        return word + "way"
    return word[first_vowel:] + word[:first_vowel] + "ay"


