}

fn step(e: Editor, op: EditOp) -> Editor {
  let cs = split(e.text, "")
  let saved = append(e.history, (e.text, e.cur))
  return match op {
    Insert(t) => insert(e, t, saved),
    Delete(n) => delete(e, min(n, e.cur), saved),
    Left(n) => Editor { text: e.text, cur: max(0, e.cur - n), history: saved },
    Right(n) => Editor { text: e.text, cur: min(len(cs), e.cur + n), history: saved },
    Undo => undo(e),
  }
}

