        return "invalid"
    if x_line and o_line:
        return "invalid"
    if x_line and xs != os + 1:
        return "invalid"
    if o_line and xs != os:
        return "invalid"

    if x_line:
        return "X wins"
    if o_line:
        return "O wins"
    if "." not in cells:
        return "draw"
    return "in progress"

