    """Simulate a keypad lock and return its final state."""
    state = "locked"
    buffer: deque[str] = deque(maxlen=len(code))
    failures = 0
    for event in events:
        if state == "blocked":
            break
        if state == "open":
            if event["kind"] == "Enter":
                state = "locked"
                buffer.clear()
            continue
        if event["kind"] == "Digit":
            buffer.append(str(event["d"]))
        elif event["kind"] == "Clear":
            buffer.clear()
        else:
            if "".join(buffer) == code:
                state = "open"
                failures = 0
            else:
                failures += 1
                if failures >= MAX_FAILURES:
                    state = "blocked"
            buffer.clear()
    return state

